[['percent','Percentage Calculator','%','Percentage निकालें'],['percentchange','Percentage Change','📈','Percentage change'],['emi','EMI Calculator','💳','Loan EMI निकालें'],['gst','GST Calculator','₹','GST जोड़ें/हटाएँ'],['discount','Discount Calculator','🏷️','Discount और final price'],['bmi','BMI Calculator','⚖️','BMI calculate करें'],['age','Age Calculator','🎂','Age calculate करें'],['datediff','Date Difference','📅','दो dates का अंतर'],['simpleinterest','Simple Interest','💰','Simple interest'],['compoundinterest','Compound Interest','📈','Compound interest'],['profitloss','Profit / Loss','💹','Profit/loss और percent'],['average','Average Calculator','➗','Numbers का average'],['ratio','Ratio Calculator','⚖️','Ratio simplify करें'],['marks','Marks Percentage','📝','Marks percentage'],['cgpa','CGPA Converter','🎓','CGPA ↔ percentage'],['tip','Tip Calculator','🍽️','Tip और split bill'],['fuel','Fuel Cost','⛽','Trip fuel cost'],['speed','Speed Calculator','🚗','Speed/distance/time'],['area','Area Calculator','📐','Common shapes area'],['volume','Volume Calculator','📦','Common shapes volume'],['gcdlcm','GCD & LCM','🔢','GCD और LCM'],['factorial','Factorial','❗','Factorial निकालें'],['prime','Prime Checker','🔍','Prime number check'],['fibonacci','Fibonacci','🌀','Fibonacci series'],['table','Multiplication Table','✖️','Table बनाएं'],['fraction','Fraction Calculator','½','Fraction operations'],['baseconvert','Number Base Converter','2️⃣','Binary/decimal/hex'],['random','Random Number','🎲','Random number'],['dice','Dice Roller','🎲','Dice roll करें'],['numwords','Number to Words','🔤','Number को words में'],['unit','Unit Converter','📏','Length/weight/temp'],['timezone','Timezone Info','🌍','UTC offset conversion']].forEach(x=>add(x[0],x[1],x[2],'Calculator',x[3],'calc',{sub:x[0]}));
// Utility/security/developer/SEO
[['password','Password Generator','🔐','Strong password बनाएँ'],['uuid','UUID Generator','🆔','UUID v4 generate करें'],['qrcode','QR Code Generator','▦','QR code बनाएँ'],['timestamp','Unix Timestamp','⏱️','Unix timestamp convert करें'],['lorem','Lorem Ipsum','📜','Dummy text generate करें'],['json2csv','JSON → CSV','↔️','JSON को CSV में बदलें'],['csv2json','CSV → JSON','↔️','CSV को JSON में बदलें'],['urlencode','URL Encoder / Decoder','🔗','URL encode/decode'],['htmlentity','HTML Entity Encoder','🌐','HTML entities encode/decode'],['base64','Base64 Encoder / Decoder','🔒','Base64 encode/decode'],['jwt','JWT Decoder','🎫','JWT payload देखें'],['sha256','SHA-256 Hash','#️⃣','SHA-256 hash बनाएं'],['regex','Regex Tester','🧪','Regular expression test'],['color','Color Converter','🎨','HEX/RGB/HSL conversion'],['query','Query String Parser','🔎','URL query parse करें'],['urlparse','URL Parser','🌐','URL parts देखें'],['htmlpreview','HTML Preview','🌐','HTML live preview'],['jsonescape','JSON Escape','🧩','JSON string escape/unescape'],['binary','Binary ↔ Text','0️⃣','Binary text conversion'],['hextext','Hex ↔ Text','🔢','Hex text conversion'],['mimetype','MIME Type Finder','📁','Extension का MIME type'],['metatags','Meta Tag Generator','🏷️','SEO meta tags बनाएं'],['robots','Robots.txt Generator','🤖','robots.txt बनाएं'],['sitemap','Sitemap Generator','🗺️','Sitemap XML बनाएं'],['opengraph','Open Graph Tags','📣','OG tags बनाएं'],['schema','Schema JSON-LD','🧾','Basic JSON-LD schema'],['businessdays','Business Days','💼','Working days calculate'],['countdown','Countdown Calculator','⏳','Date countdown'],['dateadd','Date Add/Subtract','➕','Date में days जोड़ें'],['dayofweek','Day of Week','📆','Date का weekday'],['recorder','Audio Recorder','🎙️','Microphone से audio रिकॉर्ड'],['videorecorder','Video Recorder','🎥','Camera से video रिकॉर्ड'],['snapshot','Camera Snapshot','📸','Camera photo लें'],['filehash','File SHA-256','#️⃣','File का SHA-256 hash'],['fileinfo','File Info','ℹ️','File metadata देखें']].forEach(x=>add(x[0],x[1],x[2], x[0].startsWith('meta')||['robots','sitemap','opengraph','schema'].includes(x[0])?'SEO':(['password','uuid','sha256','filehash'].includes(x[0])?'Security':(['recorder'].includes(x[0])?'Audio':(['videorecorder','snapshot'].includes(x[0])?'Video':'Developer'))),x[3],x[0]==='qrcode'?'qr':x[0]==='htmlpreview'?'htmlpreview':x[0]==='recorder'?'recorder':x[0]==='videorecorder'?'videorecorder':x[0]==='snapshot'?'snapshot':x[0]==='filehash'?'filehash':x[0]==='fileinfo'?'fileinfo':'utility',{sub:x[0]}));

const iconCat=c=>c;
$('#stats').textContent=`${tools.length}+ tools • Preview & Download • Responsive UI`;
function renderCats(){ $('#cats').innerHTML=cats.map(c=>`<button class="cat ${state.cat===c?'active':''}" data-cat="${c}">${c}</button>`).join(''); $$('.cat').forEach(b=>b.onclick=()=>{state.cat=b.dataset.cat;render();}); }
function render(){renderCats(); const q=($('#search').value||'').trim().toLowerCase(); const list=tools.filter(t=>(state.cat==='All'||t.cat===state.cat)&&(!q||`${t.name} ${t.desc} ${t.cat}`.toLowerCase().includes(q))); $('#grid').innerHTML=list.map(t=>`<article class="card" data-id="${t.id}"><span class="pill">${esc(t.cat)}</span><div class="icon">${t.icon}</div><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p></article>`).join('')||`<div class="result"><b>कोई tool नहीं मिला।</b><p class="muted">दूसरा keyword try करें।</p></div>`; $$('.card').forEach(c=>c.onclick=()=>openTool(c.dataset.id));}
$('#search').addEventListener('input',render); $('#close').onclick=closeTool; $('#pclose').onclick=closePreview; $('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeTool()}); $('#previewModal').addEventListener('click',e=>{if(e.target.id==='previewModal')closePreview()});
function openTool(id){const t=tools.find(x=>x.id===id); if(!t)return; state.current=t; $('#content').innerHTML=`<div class="toolhead"><h2>${t.icon} ${esc(t.name)}</h2><div class="muted">${esc(t.desc)} • Fast browser-based tool</div></div>${toolUI(t)}`; $('#modal').classList.add('show'); $('#modal').setAttribute('aria-hidden','false'); bindTool(t);}
function closeTool(){$('#modal').classList.remove('show');$('#modal').setAttribute('aria-hidden','true');}
function closePreview(){if(state.previewUrl){URL.revokeObjectURL(state.previewUrl);state.previewUrl=null}$('#previewModal').classList.remove('show');}
function fileField(id,accept,multiple=false,label='File Upload'){return `<div class="field full"><label>${label}</label><input class="fileinput" id="${id}" type="file" accept="${accept}" ${multiple?'multiple':''}></div>`}
function commonActions(){return `<div class="actions"><button class="btn" id="process">⚡ Process</button><button class="btn blue hidden" id="view">👁️ View Preview</button><button class="btn download hidden" id="download">⬇️ Download</button></div><div id="result"></div>`}
function toolUI(t){
 const k=t.kind,s=t.sub;
 if(['image-pdf','pdf-jpg','image-convert','image-compress','image-resize','image-crop','image-rotate','image-watermark','image-gray','image-adjust','image-blur','image-pixelate','image-info','image-base64','favicon'].includes(k)){
  let accept=k==='pdf-jpg'?'application/pdf':'image/*'; let multi=k==='image-pdf'; let extra='';
  if(k==='image-pdf')extra=`<div class="field"><label>Page Size</label><select id="size"><option>A4</option><option>Letter</option><option>Original</option></select></div><div class="field"><label>Orientation</label><select id="orient"><option>Portrait</option><option>Landscape</option></select></div><div class="field"><label>Margin (mm)</label><input id="margin" type="number" value="10" min="0" max="50"></div>`;
  if(k==='pdf-jpg')extra=`<div class="field"><label>JPG Quality</label><input id="quality" type="range" min="0.5" max="1" step="0.05" value="0.9"></div><div class="field"><label>DPI scale</label><select id="scale"><option value="1">1x</option><option value="1.5">1.5x</option><option value="2">2x</option></select></div>`;
  if(k==='image-convert')extra=`<div class="field"><label>Quality</label><input id="quality" type="range" min="0.1" max="1" step="0.05" value="0.9"></div><div class="field"><label>Background (PNG → JPG)</label><input id="bg" type="color" value="#ffffff"></div>`;
  if(k==='image-compress')extra=`<div class="field"><label>Quality</label><input id="quality" type="range" min="0.1" max="1" step="0.05" value="0.7"></div><div class="field"><label>Max Width</label><input id="maxw" type="number" value="1920" min="100"></div><div class="field"><label>Output</label><select id="fmt"><option value="image/jpeg">JPG</option><option value="image/webp">WebP</option><option value="image/png">PNG</option></select></div>`;
  if(k==='image-resize')extra=`<div class="field"><label>Width (px)</label><input id="w" type="number" min="1"></div><div class="field"><label>Height (px)</label><input id="h" type="number" min="1"></div><div class="field"><label>Keep aspect ratio</label><select id="keep"><option value="1">Yes</option><option value="0">No</option></select></div><div class="field"><label>Output</label><select id="fmt"><option value="image/jpeg">JPG</option><option value="image/png">PNG</option><option value="image/webp">WebP</option></select></div>`;
  if(k==='image-crop')extra=`<div class="field"><label>X</label><input id="x" type="number" value="0"></div><div class="field"><label>Y</label><input id="y" type="number" value="0"></div><div class="field"><label>Width</label><input id="w" type="number"></div><div class="field"><label>Height</label><input id="h" type="number"></div>`;
  if(k==='image-rotate')extra=`<div class="field"><label>Rotate</label><select id="deg"><option value="0">0°</option><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select></div><div class="field"><label>Flip</label><select id="flip"><option value="none">None</option><option value="x">Horizontal</option><option value="y">Vertical</option></select></div>`;
  if(k==='image-watermark')extra=`<div class="field"><label>Watermark text</label><input id="text" value="ToolGhar"></div><div class="field"><label>Opacity</label><input id="opacity" type="range" min="0.1" max="1" step="0.05" value="0.5"></div><div class="field"><label>Font size</label><input id="fs" type="number" value="42"></div>`;
  if(k==='image-adjust')extra=`<div class="field"><label>Brightness</label><input id="bright" type="range" min="-100" max="100" value="0"></div><div class="field"><label>Contrast</label><input id="contrast" type="range" min="-100" max="100" value="0"></div>`;
  if(k==='image-blur')extra=`<div class="field"><label>Blur (px)</label><input id="blur" type="number" min="0" max="30" value="5"></div>`;
  if(k==='image-pixelate')extra=`<div class="field"><label>Pixel size</label><input id="pixel" type="number" min="2" max="50" value="10"></div>`;
  return `<div class="form">${fileField('file',accept,multi)}${extra}</div>${commonActions()}`;
 }
 if(['merge-pdf','split-pdf','compress-pdf','rotate-pdf','watermark-pdf','pdf-info','pdf-text','pdf-numbers'].includes(k)){
  let extra=''; if(k==='split-pdf')extra=`<div class="field"><label>Pages / range</label><input id="pages" placeholder="1-3,5"></div>`;
  if(k==='rotate-pdf')extra=`<div class="field"><label>Pages</label><input id="pages" placeholder="all or 1-3"></div><div class="field"><label>Degrees</label><select id="deg"><option>90</option><option>180</option><option>270</option></select></div>`;
  if(k==='watermark-pdf')extra=`<div class="field"><label>Watermark text</label><input id="text" value="ToolGhar"></div><div class="field"><label>Opacity</label><input id="opacity" type="range" min="0.1" max="0.8" step="0.05" value="0.25"></div>`;
  if(k==='pdf-numbers')extra=`<div class="field"><label>Start number</label><input id="start" type="number" value="1"></div>`;
  return `<div class="form">${fileField('file','application/pdf',k==='merge-pdf')} ${extra}</div>${commonActions()}`;
 }
 if(t.cat==='Text')return textUI(s);
 if(t.cat==='Calculator')return calcUI(s);
 if(t.id==='password')return `<div class="form"><div class="field"><label>Length</label><input id="len" type="number" value="16" min="4" max="128"></div><div class="field"><label>Count</label><input id="count" type="number" value="1" min="1" max="50"></div></div><div class="checks"><label><input id="up" type="checkbox" checked> Uppercase</label><label><input id="lo" type="checkbox" checked> Lowercase</label><label><input id="nu" type="checkbox" checked> Numbers</label><label><input id="sy" type="checkbox" checked> Symbols</label></div>${commonActions()}`;
 if(t.id==='qrcode')return `<div class="form"><div class="field full"><label>Text / URL</label><input id="text" value="https://toolghar.example"></div><div class="field"><label>Size</label><select id="size"><option>256</option><option>320</option><option>512</option></select></div></div>${commonActions()}`;
 if(['recorder','videorecorder','snapshot'].includes(t.id))return `<div class="form"><div class="field full"><div class="drop" id="mediaStatus">Browser permission required. Start button दबाएँ।</div></div></div><div class="actions"><button class="btn" id="start">▶ Start</button><button class="btn secondary" id="stop">⏹ Stop</button><button class="btn blue hidden" id="view">👁️ View Preview</button><button class="btn download hidden" id="download">⬇️ Download</button></div><div id="result"></div>`;
 if(t.id==='htmlpreview')return `<div class="field"><label>HTML</label><textarea id="html" placeholder="<h1>Hello ToolGhar</h1>"></textarea></div><div class="actions"><button class="btn" id="process">⚡ Preview</button></div><iframe id="frame" style="width:100%;height:420px;border:1px solid #29394b;border-radius:10px;background:white"></iframe>`;
 if(t.id==='filehash'||t.id==='fileinfo')return `<div class="form">${fileField('file','*/*')}</div>${commonActions()}`;
 if(t.id==='base64image')return `<div class="form">${fileField('file','image/*')}</div>${commonActions()}`;
 if(t.id==='base64toimage')return `<div class="field"><label>Image Base64</label><textarea id="text" placeholder="data:image/png;base64,..."></textarea></div>${commonActions()}`;
 return utilityUI(t.id);
}
function textUI(s){let controls=''; if(s==='case')controls=`<div class="field"><label>Mode</label><select id="mode"><option value="upper">UPPERCASE</option><option value="lower">lowercase</option><option value="title">Title Case</option><option value="sentence">Sentence case</option><option value="toggle">tOGGLE cASE</option></select></div>`; if(s==='findreplace')controls=`<div class="field"><label>Find</label><input id="find"></div><div class="field"><label>Replace</label><input id="rep"></div>`; if(s==='repeattext')controls=`<div class="field"><label>Repeat count</label><input id="count" type="number" min="1" max="1000" value="3"></div>`; if(s==='csvtext')controls=`<div class="field"><label>Column number (1-based)</label><input id="col" type="number" value="1" min="1"></div><div class="field"><label>Delimiter</label><input id="delim" value=","></div>`; if(s==='textcsv')controls=`<div class="field"><label>Delimiter</label><select id="delim"><option>,</option><option>;</option><option>\t</option></select></div>`; return `<div class="field full"><label>📁 Upload Text File (optional)</label><input class="fileinput" id="uploadText" type="file" accept=".txt,.csv,.json,.log,.md"></div><div class="field full"><label>Text</label><textarea id="text" placeholder="यहाँ text डालें..."></textarea></div><div class="form">${controls}</div>${commonActions()}`;}
function calcUI(s){let f=''; const inp=(id,label,val='')=>`<div class="field"><label>${label}</label><input id="${id}" type="number" ${val!==''?'value="'+val+'"':''}></div>`;
 if(s==='percent')f=inp('a','Value')+inp('b','Percent %'); else if(s==='percentchange')f=inp('a','Old value')+inp('b','New value'); else if(s==='emi')f=inp('p','Principal')+inp('r','Annual interest %',10)+inp('n','Months',60); else if(s==='gst')f=inp('a','Amount')+inp('g','GST %',18)+`<div class="field"><label>Mode</label><select id="mode"><option value="add">Add GST</option><option value="remove">Remove GST</option></select></div>`; else if(s==='discount')f=inp('a','Original price')+inp('d','Discount %'); else if(s==='bmi')f=inp('w','Weight kg')+inp('h','Height cm'); else if(s==='age')f=`<div class="field"><label>Birth date</label><input id="birth" type="date"></div><div class="field"><label>As of</label><input id="asof" type="date" value="${new Date().toISOString().slice(0,10)}"></div>`; else if(s==='datediff')f=`<div class="field"><label>Start</label><input id="a" type="date"></div><div class="field"><label>End</label><input id="b" type="date"></div>`; else if(['simpleinterest','compoundinterest'].includes(s))f=inp('p','Principal')+inp('r','Annual rate %')+inp('t','Time (years)'); else if(s==='profitloss')f=inp('c','Cost price')+inp('s','Selling price'); else if(s==='average')f=`<div class="field full"><label>Numbers (comma separated)</label><input id="nums" placeholder="10,20,30"></div>`; else if(s==='ratio')f=inp('a','First')+inp('b','Second'); else if(s==='marks')f=inp('obt','Obtained')+inp('max','Maximum'); else if(s==='cgpa')f=inp('cgpa','CGPA'); else if(s==='tip')f=inp('bill','Bill')+inp('tip','Tip %',10)+inp('people','People',1); else if(s==='fuel')f=inp('distance','Distance km')+inp('mileage','Mileage km/l')+inp('price','Fuel price/l'); else if(s==='speed')f=inp('distance','Distance')+inp('time','Time hours'); else if(s==='area')f=`<div class="field"><label>Shape</label><select id="shape"><option value="circle">Circle</option><option value="rectangle">Rectangle</option><option value="triangle">Triangle</option></select></div><div class="field"><label>Value A</label><input id="a" type="number"></div><div class="field"><label>Value B (rectangle/triangle)</label><input id="b" type="number"></div>`; else if(s==='volume')f=`<div class="field"><label>Shape</label><select id="shape"><option value="cube">Cube</option><option value="box">Box</option><option value="cylinder">Cylinder</option></select></div><div class="field"><label>A / side / radius</label><input id="a" type="number"></div><div class="field"><label>B / height</label><input id="b" type="number"></div><div class="field"><label>C / length</label><input id="c" type="number"></div>`; else if(s==='gcdlcm')f=`<div class="field full"><label>Numbers</label><input id="nums" placeholder="12,18,24"></div>`; else if(s==='factorial')f=inp('n','Number',5); else if(s==='prime')f=inp('n','Number',97); else if(s==='fibonacci')f=inp('n','Terms',10); else if(s==='table')f=inp('n','Number',7)+inp('to','Up to',20); else if(s==='fraction')f=`<div class="field"><label>Numerator 1</label><input id="a" type="number"></div><div class="field"><label>Denominator 1</label><input id="b" type="number" value="1"></div><div class="field"><label>Numerator 2</label><input id="c" type="number"></div><div class="field"><label>Denominator 2</label><input id="d" type="number" value="1"></div><div class="field"><label>Operation</label><select id="op"><option>+</option><option>-</option><option>×</option><option>÷</option></select></div>`; else if(s==='baseconvert')f=inp('n','Number',255)+`<div class="field"><label>From base</label><select id="from"><option>10</option><option>2</option><option>8</option><option>16</option></select></div><div class="field"><label>To base</label><select id="to"><option>2</option><option>10</option><option>8</option><option>16</option></select></div>`; else if(s==='random')f=inp('min','Minimum',1)+inp('max','Maximum',100)+inp('count','Count',1); else if(s==='dice')f=inp('count','Dice count',2)+inp('sides','Sides',6); else if(s==='numwords')f=inp('n','Number',1234); else if(s==='unit')f=`<div class="field"><label>Category</label><select id="cat"><option value="length">Length</option><option value="weight">Weight</option><option value="temp">Temperature</option></select></div><div class="field"><label>From</label><select id="from"><option>m</option><option>km</option><option>ft</option><option>mi</option><option>kg</option><option>g</option><option>lb</option><option>c</option><option>f</option></select></div><div class="field"><label>To</label><select id="to"><option>m</option><option>km</option><option>ft</option><option>mi</option><option>kg</option><option>g</option><option>lb</option><option>c</option><option>f</option></select></div>${inp('v','Value',1)}`; else if(s==='timezone')f=`<div class="field"><label>Date/time</label><input id="dt" type="datetime-local"></div><div class="field"><label>UTC offset hours</label><input id="offset" type="number" value="5.5"></div>`; return `<div class="form">${f}</div>${commonActions()}`;}
function utilityUI(id){let body=''; if(['base64','urlencode','htmlentity','jsonescape','binary','hextext'].includes(id))body=`<div class="field"><label>Input</label><textarea id="text"></textarea></div><div class="field"><label>Mode</label><select id="mode"><option value="encode">Encode</option><option value="decode">Decode</option></select></div>`; else if(id==='uuid')body=`<div class="field"><label>Count</label><input id="count" type="number" min="1" max="100" value="5"></div>`; else if(id==='timestamp')body=`<div class="field"><label>Unix timestamp (blank = now)</label><input id="ts" type="number"></div>`; else if(id==='lorem')body=`<div class="field"><label>Paragraphs</label><input id="n" type="number" value="3" min="1" max="50"></div>`; else if(id==='json2csv'||id==='csv2json')body=`<div class="field"><label>Input</label><textarea id="text" placeholder="Paste JSON or CSV"></textarea></div>`; else if(id==='urlparse')body=`<div class="field"><label>URL</label><input id="text" placeholder="https://example.com/a?x=1"></div>`; else if(id==='query')body=`<div class="field"><label>Query string / URL</label><input id="text" placeholder="?a=1&b=hello"></div>`; else if(id==='jwt')body=`<div class="field"><label>JWT</label><textarea id="text"></textarea></div>`; else if(id==='sha256')body=`<div class="field"><label>Text</label><textarea id="text"></textarea></div>`; else if(id==='regex')body=`<div class="field"><label>Text</label><textarea id="text"></textarea></div><div class="field"><label>Pattern</label><input id="pattern" placeholder="\\d+"></div><div class="field"><label>Flags</label><input id="flags" value="g"></div>`; else if(id==='color')body=`<div class="field"><label>Color</label><input id="text" value="#9cf36c"></div>`; else if(id==='mimetype')body=`<div class="field"><label>Extension</label><input id="text" value=".pdf"></div>`; else if(id==='metatags')body=`<div class="form"><div class="field"><label>Title</label><input id="title"></div><div class="field"><label>Description</label><input id="desc"></div><div class="field full"><label>URL</label><input id="url"></div></div>`; else if(id==='robots')body=`<div class="form"><div class="field"><label>User-agent</label><input id="ua" value="*"></div><div class="field"><label>Disallow</label><input id="disallow" placeholder="/private/"></div></div>`; else if(id==='sitemap')body=`<div class="field"><label>URLs (one per line)</label><textarea id="text" placeholder="https://example.com/\nhttps://example.com/about"></textarea></div>`; else if(id==='opengraph')body=`<div class="form"><div class="field"><label>Title</label><input id="title"></div><div class="field"><label>Description</label><input id="desc"></div><div class="field"><label>Image URL</label><input id="image"></div><div class="field"><label>Page URL</label><input id="url"></div></div>`; else if(id==='schema')body=`<div class="form"><div class="field"><label>Name</label><input id="name"></div><div class="field"><label>Description</label><input id="desc"></div><div class="field"><label>URL</label><input id="url"></div></div>`; else if(id==='businessdays')body=`<div class="field"><label>Start</label><input id="a" type="date"></div><div class="field"><label>End</label><input id="b" type="date"></div>`; else if(id==='countdown'||id==='dayofweek')body=`<div class="field"><label>Date</label><input id="date" type="date"></div>`; else if(id==='dateadd')body=`<div class="field"><label>Date</label><input id="date" type="date"></div><div class="field"><label>Days (+/-)</label><input id="days" type="number" value="30"></div>`; else body=`<div class="field"><label>Input</label><textarea id="text" placeholder="यहाँ input डालें..."></textarea></div>`; return `<div class="form">${body}</div>${commonActions()}`;}
function bindTool(t){const p=$('#process'),view=$('#view'),dl=$('#download'); if($('#uploadText'))$('#uploadText').onchange=async e=>{const f=e.target.files[0];if(f)$('#text').value=await f.text()}; if(p)p.onclick=()=>run(t); if(view)view.onclick=()=>previewLast(); if(dl)dl.onclick=()=>downloadLast(); if(t.id==='htmlpreview')p.onclick=()=>{$('#frame').srcdoc=$('#html').value}; if(['recorder','videorecorder','snapshot'].includes(t.id))bindMedia(t);}
async function run(t){try{let out=await handlers[t.kind]?.(t); if(out===undefined)out=await handlers.utility(t); showResult(out);}catch(e){showError(e)}}
function showError(e){$('#result').innerHTML=`<div class="result danger">❌ ${esc(e.message||e)}</div>`;}
function showResult(out){state.lastBlob=out.blob||null;state.lastName=out.name||'toolghar-result.txt'; const r=$('#result'); r.innerHTML=out.html||`<div class="result"><pre>${esc(out.text||'Done')}</pre></div>`; if(out.blob){$('#view')?.classList.remove('hidden');$('#download')?.classList.remove('hidden');} else if(out.text!==undefined){const blob=new Blob([out.text],{type:out.type||'text/plain'});state.lastBlob=blob;$('#view')?.classList.remove('hidden');$('#download')?.classList.remove('hidden');}}
function downloadLast(){if(!state.lastBlob)return toast('पहले Process करें');const a=document.createElement('a');a.href=URL.createObjectURL(state.lastBlob);a.download=state.lastName;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function previewLast(){if(!state.lastBlob)return toast('पहले Process करें');const b=state.lastBlob; if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);state.previewUrl=URL.createObjectURL(b); const c=$('#previewContent'); if(b.type.startsWith('image/'))c.innerHTML=`<img class="previewmedia" src="${state.previewUrl}">`; else if(b.type==='application/pdf')c.innerHTML=`<iframe class="previewpdf" src="${state.previewUrl}"></iframe>`; else if(b.type.startsWith('text/')||b.type.includes('json')||b.type.includes('javascript')||b.type.includes('xml')){b.text().then(x=>c.innerHTML=`<pre class="previewtext">${esc(x)}</pre>`)} else c.innerHTML=`<div class="result"><h3>File ready</h3><p class="muted">${esc(state.lastName)} • ${(b.size/1024).toFixed(1)} KB</p></div>`; $('#previewDownload').onclick=downloadLast;$('#previewModal').classList.add('show');}
const handlers={};
handlers['image-pdf']=async()=>{const fs=[...$('#file').files];if(!fs.length)throw Error('कम से कम एक image चुनें');const doc=await PDFLib.PDFDocument.create();for(const f of fs){const bytes=await f.arrayBuffer();let img; if(f.type==='image/png')img=await doc.embedPng(bytes); else img=await doc.embedJpg(bytes); const size=$('#size').value,margin=Number($('#margin').value)||0; let pw,ph;if(size==='A4'){pw=595.28;ph=841.89}else if(size==='Letter'){pw=612;ph=792}else{pw=img.width;ph=img.height}if($('#orient').value==='Landscape'&&size!=='Original')[pw,ph]=[ph,pw];const page=doc.addPage([pw,ph]);const maxw=pw-margin*2,maxh=ph-margin*2;const sc=Math.min(maxw/img.width,maxh/img.height);page.drawImage(img,{x:(pw-img.width*sc)/2,y:(ph-img.height*sc)/2,width:img.width*sc,height:img.height*sc});}return {blob:new Blob([await doc.save()],{type:'application/pdf'}),name:'toolghar-images.pdf',html:`<div class="result success">PDF तैयार है • ${fs.length} image(s)</div>`}};
handlers['pdf-jpg']=async()=>{const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');if(!window.pdfjsLib)throw Error('PDF library load नहीं हुई');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,zip=new JSZip(),scale=Number($('#scale').value);for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),v=page.getViewport({scale});const can=document.createElement('canvas');can.width=v.width;can.height=v.height;await page.render({canvasContext:can.getContext('2d'),viewport:v}).promise;const blob=await new Promise(r=>can.toBlob(r,'image/jpeg',Number($('#quality').value)));zip.file(`page-${i}.jpg`,await blob.arrayBuffer())}return {blob:await zip.generateAsync({type:'blob'}),name:'pdf-pages.zip',html:`<div class="result success">${pdf.numPages} pages JPG में तैयार। ZIP download करें।</div>`}};
async function loadImage(f){return await createImageBitmap(f)}
async function canvasImage(mode){const f=$('#file').files[0];if(!f)throw Error('Image चुनें');const img=await loadImage(f);let w=img.width,h=img.height;const can=document.createElement('canvas');let ctx=can.getContext('2d');let outType='image/png',quality=0.9;if(mode==='convert'){outType=state.current.to;quality=Number($('#quality').value);can.width=w;can.height=h;ctx.fillStyle=$('#bg')?.value||'#fff';if(outType==='image/jpeg')ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0)}else if(mode==='resize'){w=Number($('#w').value)||w;h=Number($('#h').value)||h;if($('#keep').value==='1'){const ratio=img.width/img.height;if(w&&!$('#h').value)h=Math.round(w/ratio);else if(h&&!$('#w').value)w=Math.round(h*ratio);else{const r=Math.min(w/img.width,h/img.height);w=Math.round(img.width*r);h=Math.round(img.height*r)}}can.width=w;can.height=h;ctx.drawImage(img,0,0,w,h);outType=$('#fmt').value;quality=.9}else if(mode==='crop'){const x=Number($('#x').value),y=Number($('#y').value),cw=Number($('#w').value)||img.width-x,ch=Number($('#h').value)||img.height-y;w=cw;h=ch;can.width=w;can.height=h;ctx.drawImage(img,x,y,cw,ch,0,0,w,h);outType='image/png'}else if(mode==='rotate'){const d=Number($('#deg').value);if(d===90||d===270)[w,h]=[h,w];can.width=w;can.height=h;ctx.translate(w/2,h/2);ctx.rotate(d*Math.PI/180);let sx=$('#flip').value==='x'?-1:1,sy=$('#flip').value==='y'?-1:1;ctx.scale(sx,sy);ctx.drawImage(img,-img.width/2,-img.height/2);outType='image/png'}else if(mode==='watermark'){can.width=w;can.height=h;ctx.drawImage(img,0,0);ctx.globalAlpha=Number($('#opacity').value);ctx.fillStyle='#ffffff';ctx.font=`${Number($('#fs').value)||42}px Arial`;ctx.textAlign='center';ctx.fillText($('#text').value||'ToolGhar',w/2,h/2);outType='image/png'}else if(mode==='gray'||mode==='adjust'||mode==='blur'||mode==='pixel'){can.width=w;can.height=h;ctx.filter=mode==='gray'?'grayscale(1)':mode==='blur'?`blur(${Number($('#blur').value)||5}px)`:mode==='adjust'?`brightness(${100+Number($('#bright').value)}%) contrast(${100+Number($('#contrast').value)}%)`:'none';ctx.drawImage(img,0,0);if(mode==='pixel'){const p=Math.max(2,Number($('#pixel').value));const small=document.createElement('canvas');small.width=Math.max(1,Math.floor(w/p));small.height=Math.max(1,Math.floor(h/p));small.getContext('2d').drawImage(img,0,0,small.width,small.height);ctx.imageSmoothingEnabled=false;ctx.drawImage(small,0,0,w,h)}outType='image/png'}const blob=await new Promise(r=>can.toBlob(r,outType,quality));return {blob,name:`toolghar-${mode}.${outType==='image/png'?'png':outType.includes('webp')?'webp':'jpg'}`,html:`<div class="result"><img src="${URL.createObjectURL(blob)}" class="previewmedia"><p class="small">${w}×${h} • ${(blob.size/1024).toFixed(1)} KB</p></div>`}}
handlers['image-convert']=()=>canvasImage('convert');handlers['image-resize']=()=>canvasImage('resize');handlers['image-crop']=()=>canvasImage('crop');handlers['image-rotate']=()=>canvasImage('rotate');handlers['image-watermark']=()=>canvasImage('watermark');handlers['image-gray']=()=>canvasImage('gray');handlers['image-adjust']=()=>canvasImage('adjust');handlers['image-blur']=()=>canvasImage('blur');handlers['image-pixelate']=()=>canvasImage('pixel');handlers['image-compress']=async()=>{const f=$('#file').files[0];if(!f)throw Error('Image चुनें');const img=await loadImage(f);let w=img.width;if(w>Number($('#maxw').value))w=Number($('#maxw').value);const h=Math.round(img.height*w/img.width);const can=document.createElement('canvas');can.width=w;can.height=h;can.getContext('2d').drawImage(img,0,0,w,h);const type=$('#fmt').value,q=Number($('#quality').value);const blob=await new Promise(r=>can.toBlob(r,type,q));return {blob,name:`compressed.${type.split('/')[1]}`,html:`<div class="result"><img src="${URL.createObjectURL(blob)}" class="previewmedia"><p>Original: ${(f.size/1024).toFixed(1)} KB → Output: ${(blob.size/1024).toFixed(1)} KB</p></div>`}};
handlers['image-info']=async()=>{const f=$('#file').files[0];if(!f)throw Error('Image चुनें');const img=await loadImage(f);return {text:`Name: ${f.name}\nType: ${f.type}\nSize: ${(f.size/1024).toFixed(1)} KB\nWidth: ${img.width}px\nHeight: ${img.height}px`,name:'image-info.txt'}};
handlers['image-base64']=async()=>{const f=$('#file').files[0];if(!f)throw Error('Image चुनें');const b=await f.arrayBuffer();const s=`data:${f.type};base64,${bytesToB64(new Uint8Array(b))}`;return {text:s,name:'image-base64.txt'}};
handlers['base64-image']=async()=>{let s=$('#text').value.trim();if(!s.startsWith('data:image/'))throw Error('Data URL format चाहिए');const [head,data]=s.split(',');const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));const type=head.slice(5).split(';')[0];return {blob:new Blob([bytes],{type}),name:`decoded.${type.split('/')[1]}`,html:`<div class="result"><img src="${URL.createObjectURL(new Blob([bytes],{type}))}" class="previewmedia"></div>`}};
handlers['favicon']=async()=>{const f=$('#file').files[0];if(!f)throw Error('Image चुनें');const img=await loadImage(f),c=document.createElement('canvas');c.width=64;c.height=64;c.getContext('2d').drawImage(img,0,0,64,64);const b=await new Promise(r=>c.toBlob(r,'image/png'));return {blob:b,name:'favicon.png',html:`<div class="result"><img src="${URL.createObjectURL(b)}" class="previewmedia" style="max-width:128px"></div>`}};
handlers['merge-pdf']=async()=>{const fs=[...$('#file').files];if(fs.length<1)throw Error('PDF files चुनें');const out=await PDFLib.PDFDocument.create();for(const f of fs){const d=await PDFLib.PDFDocument.load(await f.arrayBuffer());const pages=await out.copyPages(d,d.getPageIndices());pages.forEach(p=>out.addPage(p))}return {blob:new Blob([await out.save()],{type:'application/pdf'}),name:'merged.pdf',html:`<div class="result success">${fs.length} PDFs merge हो गए।</div>`}};
function parsePages(s,total){if(!s||s.toLowerCase()==='all')return [...Array(total)].map((_,i)=>i);const set=new Set();s.split(',').forEach(x=>{x=x.trim();if(x.includes('-')){let[a,b]=x.split('-').map(Number);for(let i=a;i<=b;i++)if(i>=1&&i<=total)set.add(i-1)}else{let n=Number(x);if(n>=1&&n<=total)set.add(n-1)}});return [...set].sort((a,b)=>a-b)}
handlers['split-pdf']=async()=>{const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');const d=await PDFLib.PDFDocument.load(await f.arrayBuffer()),idx=parsePages($('#pages').value,d.getPageCount());if(!idx.length)throw Error('Valid pages range दें');const o=await PDFLib.PDFDocument.create();(await o.copyPages(d,idx)).forEach(p=>o.addPage(p));return {blob:new Blob([await o.save()],{type:'application/pdf'}),name:'split.pdf',html:`<div class="result success">${idx.length} page(s) नई PDF में हैं।</div>`}};
handlers['compress-pdf']=async()=>{const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');const d=await PDFLib.PDFDocument.load(await f.arrayBuffer());const b=new Blob([await d.save({useObjectStreams:true})],{type:'application/pdf'});return {blob:b,name:'compressed.pdf',html:`<div class="result">Re-saved PDF • ${(f.size/1024).toFixed(1)} KB → ${(b.size/1024).toFixed(1)} KB. Size reduction guaranteed नहीं है।</div>`}};
async function pdfModify(type){const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');const d=await PDFLib.PDFDocument.load(await f.arrayBuffer());const idx=parsePages($('#pages')?.value,d.getPageCount());const ids=idx.length?idx:d.getPageIndices();if(type==='rotate')ids.forEach(i=>d.getPage(i).setRotation(PDFLib.degrees(Number($('#deg').value))));if(type==='watermark')ids.forEach(i=>{const p=d.getPage(i);p.drawText($('#text').value||'ToolGhar',{x:p.getWidth()/2-80,y:p.getHeight()/2,size:28,opacity:Number($('#opacity').value)||.25,color:PDFLib.rgb(0.2,.2,.2),rotate:PDFLib.degrees(30)})});if(type==='numbers')ids.forEach((i,n)=>d.getPage(i).drawText(String(Number($('#start').value||1)+n),{x:20,y:20,size:10}));const b=new Blob([await d.save()],{type:'application/pdf'});return {blob:b,name:`${type}.pdf`,html:`<div class="result success">PDF updated successfully.</div>`}}
handlers['rotate-pdf']=()=>pdfModify('rotate');handlers['watermark-pdf']=()=>pdfModify('watermark');handlers['pdf-numbers']=()=>pdfModify('numbers');
handlers['pdf-info']=async()=>{const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');const d=await PDFLib.PDFDocument.load(await f.arrayBuffer());return {text:`Name: ${f.name}\nPages: ${d.getPageCount()}\nSize: ${(f.size/1024).toFixed(1)} KB`,name:'pdf-info.txt'}};
handlers['pdf-text']=async()=>{const f=$('#file').files[0];if(!f)throw Error('PDF चुनें');if(!window.pdfjsLib)throw Error('PDF library load नहीं हुई');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const d=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;let all='';for(let i=1;i<=d.numPages;i++){const p=await d.getPage(i),c=await p.getTextContent();all+=`\n--- Page ${i} ---\n`+c.items.map(x=>x.str).join(' ')}return {text:all.trim(),name:'extracted.txt'}};
const textHandlers={words:t=>`Words: ${t.trim()?t.trim().split(/\s+/).length:0}\nCharacters: ${t.length}\nCharacters (no spaces): ${t.replace(/\s/g,'').length}\nLines: ${t? t.split(/\r?\n/).length:0}`,chars:t=>`Characters: ${t.length}`,lines:t=>`Lines: ${t?t.split(/\r?\n/).length:0}`,trim:t=>t.replace(/[ \t]+/g,' ').replace(/^ +| +$/gm,'').trim(),reverse:t=>[...t].reverse().join(''),sortlines:t=>t.split(/\r?\n/).sort((a,b)=>a.localeCompare(b)).join('\n'),duplines:t=>[...new Set(t.split(/\r?\n/))].join('\n'),dupwords:t=>[...new Set(t.split(/\s+/))].join(' '),slug:t=>t.toLowerCase().trim().replace(/[^\w\s-]/g,'').replace(/\s+/g,'-'),title:t=>t.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()),punct:t=>t.replace(/[!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~]/g,''),upper:t=>t.toUpperCase(),lower:t=>t.toLowerCase(),newline:t=>t.replace(/\r\n/g,'\n').replace(/\n{3,}/g,'\n\n'),jsonbeauty:t=>JSON.stringify(JSON.parse(t),null,2)};
handlers['text']=async t=>{let s=$('#text').value;const sub=t.sub;if(sub==='case'){const m=$('#mode').value;if(m==='upper')s=s.toUpperCase();else if(m==='lower')s=s.toLowerCase();else if(m==='title')s=s.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase());else if(m==='sentence')s=s.toLowerCase().replace(/(^|[.!?]\s+)([a-z])/g,(_,a,c)=>a+c.toUpperCase());else s=[...s].map(c=>c===c.toUpperCase()?c.toLowerCase():c.toUpperCase()).join('')}else if(sub==='findreplace')s=s.split($('#find').value).join($('#rep').value);else if(sub==='repeattext')s=Array(Number($('#count').value)||1).fill(s).join('\n');else if(sub==='csvtext'){const lines=s.split(/\r?\n/).filter(Boolean);const col=Math.max(1,Number($('#col').value)||1)-1;const d=$('#delim').value||',';s=lines.map(x=>x.split(d)[col]??'').join('\n')}else if(sub==='textcsv'){s=s.split(/\r?\n/).map(x=>JSON.stringify([x]).slice(1,-1)).join(',\n')+'\n'}else if(textHandlers[sub])s=textHandlers[sub](s);return {text:s,name:`${sub}-result.txt`}};
function val(id){return Number($('#'+id)?.value||0)}
function calcResult(s){let out='';if(s==='percent')out=`${val('b')}% of ${val('a')} = ${val('a')*val('b')/100}`;else if(s==='percentchange')out=`Percentage change = ${((val('b')-val('a'))/val('a')*100).toFixed(2)}%`;else if(s==='emi'){let p=val('p'),r=val('r')/1200,n=val('n');let e=r? p*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1):p/n;out=`Monthly EMI = ₹${e.toFixed(2)}\nTotal payment = ₹${(e*n).toFixed(2)}\nTotal interest = ₹${(e*n-p).toFixed(2)}`}else if(s==='gst'){let a=val('a'),g=val('g');out=$('#mode').value==='add'?`GST = ₹${(a*g/100).toFixed(2)}\nFinal = ₹${(a*(1+g/100)).toFixed(2)}`:`Base amount = ₹${(a/(1+g/100)).toFixed(2)}\nGST = ₹${(a-a/(1+g/100)).toFixed(2)}`; }else if(s==='discount'){let a=val('a'),d=val('d');out=`Discount = ₹${(a*d/100).toFixed(2)}\nFinal price = ₹${(a*(1-d/100)).toFixed(2)}`}else if(s==='bmi'){let b=val('w'),h=val('h')/100,x=b/(h*h);out=`BMI = ${x.toFixed(2)}\nCategory = ${x<18.5?'Underweight':x<25?'Normal':x<30?'Overweight':'Obesity'}`}else if(s==='age'){let b=new Date($('#birth').value),a=new Date($('#asof').value),y=a.getFullYear()-b.getFullYear(),m=a.getMonth()-b.getMonth();if(m<0||(m===0&&a.getDate()<b.getDate()))y--;out=`Age = ${y} years`}else if(s==='datediff'){let a=new Date($('#a').value),b=new Date($('#b').value);out=`Difference = ${Math.abs(Math.round((b-a)/86400000))} days`}else if(['simpleinterest','compoundinterest'].includes(s)){let p=val('p'),r=val('r')/100,t=val('t');let interest=s==='simpleinterest'?p*r*t:p*(Math.pow(1+r,t)-1);out=`Interest = ₹${interest.toFixed(2)}\nAmount = ₹${(p+interest).toFixed(2)}`}else if(s==='profitloss'){let c=val('c'),sp=val('s'),x=sp-c;out=`${x>=0?'Profit':'Loss'} = ₹${Math.abs(x).toFixed(2)}\nPercent = ${(Math.abs(x)/c*100).toFixed(2)}%`}else if(s==='average'){let a=$('#nums').value.split(',').map(Number).filter(Number.isFinite);out=`Average = ${a.reduce((x,y)=>x+y,0)/a.length}`}else if(s==='ratio'){let a=val('a'),b=val('b'),g=gcd(Math.abs(a),Math.abs(b));out=`Simplified ratio = ${a/g}:${b/g}`}else if(s==='marks')out=`Percentage = ${(val('obt')/val('max')*100).toFixed(2)}%`;else if(s==='cgpa')out=`Approx. percentage = ${(val('cgpa')*9.5).toFixed(2)}%`;else if(s==='tip'){let total=val('bill')*(1+val('tip')/100);out=`Tip = ₹${(val('bill')*val('tip')/100).toFixed(2)}\nTotal = ₹${total.toFixed(2)}\nPer person = ₹${(total/Math.max(1,val('people'))).toFixed(2)}`}else if(s==='fuel')out=`Fuel needed = ${(val('distance')/val('mileage')).toFixed(2)} L\nCost = ₹${(val('distance')/val('mileage')*val('price')).toFixed(2)}`;else if(s==='speed')out=`Speed = ${(val('distance')/val('time')).toFixed(2)} units/hour`;else if(s==='area'){let sh=$('#shape').value,a=val('a'),b=val('b');out=sh==='circle'?`Area = ${(Math.PI*a*a).toFixed(2)}`:sh==='rectangle'?`Area = ${(a*b).toFixed(2)}`:`Area = ${(a*b/2).toFixed(2)}`}else if(s==='volume'){let sh=$('#shape').value,a=val('a'),b=val('b'),c=val('c');out=sh==='cube'?`Volume = ${(a**3).toFixed(2)}`:sh==='box'?`Volume = ${(a*b*c).toFixed(2)}`:`Volume = ${(Math.PI*a*a*b).toFixed(2)}`}else if(s==='gcdlcm'){let a=$('#nums').value.split(',').map(Number).filter(Number.isFinite),g=a.reduce((x,y)=>gcd(x,Math.abs(y))),l=a.reduce((x,y)=>Math.abs(x*y)/gcd(x,Math.abs(y)));out=`GCD = ${g}\nLCM = ${l}`}else if(s==='factorial'){let n=Math.floor(val('n'));if(n<0||n>170)throw Error('0–170 के बीच number दें');let z=1;for(let i=2;i<=n;i++)z*=i;out=`${n}! = ${z}`}else if(s==='prime'){let n=Math.floor(val('n'));out=`${n} is ${isPrime(n)?'Prime':'Not Prime'}`}else if(s==='fibonacci'){let n=Math.min(1000,Math.max(1,Math.floor(val('n')))),a=0,b=1,r=[];for(let i=0;i<n;i++){r.push(a);[a,b]=[b,a+b]}out=r.join(', ')}else if(s==='table'){let n=val('n'),to=val('to');out=Array.from({length:to},(_,i)=>`${n} × ${i+1} = ${n*(i+1)}`).join('\n')}else if(s==='fraction'){let a=val('a'),b=val('b'),c=val('c'),d=val('d'),op=$('#op').value,n=op==='+'?a*d+c*b:op==='-'?a*d-c*b:op==='×'?a*c:a*d,den=op==='+'||op==='-'?b*d:op==='×'?b*d:b*c,g=gcd(Math.abs(n),Math.abs(den));out=`Result = ${n/g}/${den/g}`}else if(s==='baseconvert'){let n=$('#n').value,from=Number($('#from').value),to=Number($('#to').value);out=`Result = ${parseInt(n,from).toString(to).toUpperCase()}`}else if(s==='random'){let a=val('min'),b=val('max'),n=val('count');out=Array.from({length:n},()=>Math.floor(Math.random()*(b-a+1))+a).join(', ')}else if(s==='dice'){let n=val('count'),sides=val('sides'),a=Array.from({length:n},()=>Math.floor(Math.random()*sides)+1);out=`Rolls: ${a.join(', ')}\nTotal: ${a.reduce((x,y)=>x+y,0)}`}else if(s==='numwords')out=numberWords(Math.floor(val('n')));else if(s==='unit')out=unitConvert();else if(s==='timezone'){let d=new Date($('#dt').value||Date.now()),o=val('offset'),local=new Date(d.getTime()+o*3600000);out=local.toISOString().replace('T',' ').slice(0,19)+' (UTC'+(o>=0?'+':'')+o+')'}return {text:out,name:`${s}-result.txt`}}
handlers['calc']=async t=>calcResult(t.sub);
function gcd(a,b){while(b){[a,b]=[b,a%b]}return a||1}function isPrime(n){if(n<2)return false;for(let i=2;i*i<=n;i++)if(n%i===0)return false;return true}
function numberWords(n){if(!Number.isFinite(n))return '';if(n===0)return'Zero';if(n<0)return'Minus '+numberWords(-n);const o=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],t=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];function h(x){if(x<20)return o[x];if(x<100)return t[Math.floor(x/10)]+(x%10?' '+o[x%10]:'');if(x<1000)return o[Math.floor(x/100)]+' Hundred'+(x%100?' '+h(x%100):'')}let parts=[];if(n>=10000000){parts.push(h(Math.floor(n/10000000))+' Crore');n%=10000000}if(n>=100000){parts.push(h(Math.floor(n/100000))+' Lakh');n%=100000}if(n>=1000){parts.push(h(Math.floor(n/1000))+' Thousand');n%=1000}if(n)parts.push(h(n));return parts.join(' ')}
function unitConvert(){let v=val('v'),c=$('#cat').value,f=$('#from').value,t=$('#to').value;if(c==='temp'){let celsius=f==='c'?v:(f==='f'?(v-32)*5/9:v-273.15);let r=t==='c'?celsius:t==='f'?celsius*9/5+32:celsius+273.15;return `${v} ${f} = ${r}`;}let groups=c==='length'?{m:1,km:1000,ft:.3048,mi:1609.344}:{kg:1,g:.001,lb:.45359237};if(!(f in groups)||!(t in groups))return'Choose compatible units';return `${v} ${f} = ${v*groups[f]/groups[t]} ${t}`}
handlers['utility']=async t=>{const id=t.id;let s=$('#text')?.value||'';let out='';if(['base64','urlencode','htmlentity','jsonescape','binary','hextext'].includes(id)){let enc=$('#mode').value==='encode';if(id==='base64')out=enc?btoa(unescape(encodeURIComponent(s))):decodeURIComponent(escape(atob(s)));else if(id==='urlencode')out=enc?encodeURIComponent(s):decodeURIComponent(s);else if(id==='htmlentity')out=enc?esc(s):s.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&');else if(id==='jsonescape')out=enc?JSON.stringify(s):JSON.parse(s);else if(id==='binary')out=enc?[...s].map(c=>c.charCodeAt(0).toString(2).padStart(8,'0')).join(' '):s.split(/\s+/).map(x=>String.fromCharCode(parseInt(x,2))).join('');else out=enc?[...s].map(c=>c.charCodeAt(0).toString(16).padStart(2,'0')).join(' '):s.split(/\s+/).map(x=>String.fromCharCode(parseInt(x,16))).join('')}else if(id==='uuid'){let n=val('count');out=Array.from({length:n},()=>crypto.randomUUID()).join('\n')}else if(id==='timestamp'){let ts=$('#ts').value;out=ts?new Date(Number(ts)*1000).toString():Math.floor(Date.now()/1000).toString()}else if(id==='lorem'){let n=val('n');let p='Lorem ipsum dolor sit amet, consectetur adipiscing elit. Integer feugiat, nibh at commodo cursus, justo lorem placerat erat.';out=Array.from({length:n},()=>p).join('\n\n')}else if(id==='json2csv'){let a=JSON.parse(s);if(!Array.isArray(a)||!a.length)throw Error('JSON array of objects चाहिए');let keys=[...new Set(a.flatMap(x=>Object.keys(x)))];out=keys.join(',')+'\n'+a.map(x=>keys.map(k=>JSON.stringify(x[k]??'')).join(',')).join('\n')}else if(id==='csv2json'){let lines=s.split(/\r?\n/).filter(Boolean),keys=lines.shift().split(',');out=JSON.stringify(lines.map(l=>{let v=l.split(',');return Object.fromEntries(keys.map((k,i)=>[k,v[i]??'']))}),null,2)}else if(id==='urlparse'){let u=new URL(s);out=`Protocol: ${u.protocol}\nHost: ${u.host}\nPath: ${u.pathname}\nQuery: ${u.search}\nHash: ${u.hash}`}else if(id==='query'){let q=s.includes('?')?s.split('?')[1]:s;let p=new URLSearchParams(q);out=[...p.entries()].map(([k,v])=>`${k} = ${v}`).join('\n')}else if(id==='jwt'){let parts=s.split('.');if(parts.length!==3)throw Error('Valid JWT दें');out=JSON.stringify(JSON.parse(atob(parts[1].replace(/-/g,'+').replace(/_/g,'/'))),null,2)}else if(id==='sha256'){out=await digestText(s)}else if(id==='regex'){let re=new RegExp($('#pattern').value,$('#flags').value),m=[...s.matchAll(re)];out=m.map(x=>x[0]).join('\n')||'No matches'}else if(id==='color'){out=colorConvert(s)}else if(id==='mimetype'){const map={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',gif:'image/gif',webp:'image/webp',txt:'text/plain',csv:'text/csv',json:'application/json',html:'text/html',css:'text/css',js:'text/javascript',zip:'application/zip'};out=map[s.replace(/^\./,'').toLowerCase()]||'application/octet-stream'}else if(id==='metatags'){out=`<title>${esc($('#title').value)}</title>\n<meta name="description" content="${esc($('#desc').value)}">\n<link rel="canonical" href="${esc($('#url').value)}">`}else if(id==='robots')out=`User-agent: ${$('#ua').value}\nDisallow: ${$('#disallow').value||''}\nSitemap: https://example.com/sitemap.xml`;else if(id==='sitemap')out='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+s.split(/\r?\n/).filter(Boolean).map(u=>`  <url><loc>${esc(u)}</loc></url>`).join('\n')+'\n</urlset>';else if(id==='opengraph')out=`<meta property="og:title" content="${esc($('#title').value)}">\n<meta property="og:description" content="${esc($('#desc').value)}">\n<meta property="og:image" content="${esc($('#image').value)}">\n<meta property="og:url" content="${esc($('#url').value)}">`;else if(id==='schema')out=JSON.stringify({'@context':'https://schema.org','@type':'WebSite',name:$('#name').value,description:$('#desc').value,url:$('#url').value},null,2);else if(id==='businessdays'){let a=new Date($('#a').value),b=new Date($('#b').value),n=0;for(let d=new Date(Math.min(a,b));d<=new Date(Math.max(a,b));d.setDate(d.getDate()+1)){let day=d.getDay();if(day!==0&&day!==6)n++}out=`Business days = ${n}`}else if(id==='countdown'){let d=new Date($('#date').value+'T00:00:00'),ms=d-Date.now();out=ms<=0?'Date has arrived':`${Math.floor(ms/86400000)} days, ${Math.floor(ms/3600000)%24} hours, ${Math.floor(ms/60000)%60} minutes`}else if(id==='dateadd'){let d=new Date($('#date').value);d.setDate(d.getDate()+val('days'));out=d.toISOString().slice(0,10)}else if(id==='dayofweek'){out=new Date($('#date').value).toLocaleDateString(undefined,{weekday:'long'})}else if(id==='htmlentity'){}else if(id==='jsonescape'){}else out=s;return {text:String(out),name:`${id}-result.txt`}};
handlers['password']=async()=>{const len=Math.min(128,Math.max(4,val('len'))),count=Math.min(50,Math.max(1,val('count')));let chars='';if($('#up').checked)chars+='ABCDEFGHIJKLMNOPQRSTUVWXYZ';if($('#lo').checked)chars+='abcdefghijklmnopqrstuvwxyz';if($('#nu').checked)chars+='0123456789';if($('#sy').checked)chars+='!@#$%^&*()-_=+[]{}';if(!chars)throw Error('कम से कम एक character type चुनें');const arr=[];const buf=new Uint32Array(len*count);crypto.getRandomValues(buf);let j=0;for(let k=0;k<count;k++){let x='';for(let i=0;i<len;i++)x+=chars[buf[j++]%chars.length];arr.push(x)}return {text:arr.join('\n'),name:'passwords.txt'}};
handlers['qrcode']=async()=>{if(!window.QRCode)throw Error('QR library load नहीं हुई');const text=$('#text').value.trim();if(!text)throw Error('Text/URL डालें');const size=Number($('#size').value)||256;const holder=document.createElement('div');new QRCode(holder,{text,width:size,height:size,correctLevel:QRCode.CorrectLevel.H});await new Promise(r=>setTimeout(r,50));const canvas=holder.querySelector('canvas');if(!canvas)throw Error('QR generate नहीं हुआ');const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));return {blob,name:'qrcode.png',html:`<div class="result"><div class="qrbox">${canvas.outerHTML}</div></div>`}};
handlers['filehash']=async()=>{const f=$('#file').files[0];if(!f)throw Error('File चुनें');const h=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());const hex=[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('');return {text:`File: ${f.name}\nSize: ${f.size} bytes\nSHA-256: ${hex}`,name:'file-hash.txt'}};
handlers['fileinfo']=async()=>{const f=$('#file').files[0];if(!f)throw Error('File चुनें');return {text:`Name: ${f.name}\nType: ${f.type||'unknown'}\nSize: ${f.size} bytes\nLast modified: ${new Date(f.lastModified).toString()}`,name:'file-info.txt'}};
async function digestText(s){const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function colorConvert(s){let hex=s.trim();if(hex.startsWith('#')){let h=hex.slice(1);if(h.length===3)h=h.split('').map(x=>x+x).join('');let r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);return `HEX: #${h}\nRGB: rgb(${r}, ${g}, ${b})\nHSL: ${rgbHsl(r,g,b)}`}let m=s.match(/rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)/i);if(m)return `HEX: #${[1,2,3].map(i=>Number(m[i]).toString(16).padStart(2,'0')).join('')}`;return'Use #RRGGBB or rgb(r,g,b)'}function rgbHsl(r,g,b){r/=255;g/=255;b/=255;let max=Math.max(r,g,b),min=Math.min(r,g,b),h,s,l=(max+min)/2;if(max===min)h=s=0;else{let d=max-min;s=l>.5?d/(2-max-min):d/(max+min);switch(max){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4}h/=6}return`hsl(${Math.round(h*360)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%)`}
function bytesToB64(bytes){let s='';for(let i=0;i<bytes.length;i+=0x8000)s+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(s)}
async function bindMedia(t){let stream=null,rec=null,chunks=[];const status=$('#mediaStatus');$('#start').onclick=async()=>{try{const constraints=t.id==='recorder'?{audio:true}:{video:true,audio:true};stream=await navigator.mediaDevices.getUserMedia(constraints);if(t.id==='snapshot'){const v=document.createElement('video');v.srcObject=stream;await v.play();await new Promise(r=>setTimeout(r,500));const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);const b=await new Promise(r=>c.toBlob(r,'image/jpeg',.92));stream.getTracks().forEach(x=>x.stop());state.lastBlob=b;state.lastName='snapshot.jpg';$('#result').innerHTML=`<div class="result"><img class="previewmedia" src="${URL.createObjectURL(b)}"></div>`;$('#view').classList.remove('hidden');$('#download').classList.remove('hidden');return}rec=new MediaRecorder(stream);chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=()=>{const b=new Blob(chunks,{type:rec.mimeType});state.lastBlob=b;state.lastName=t.id==='recorder'?'recording.webm':'recording.webm';$('#result').innerHTML=`<div class="result success">Recording ready • ${(b.size/1024).toFixed(1)} KB</div>`;$('#view').classList.remove('hidden');$('#download').classList.remove('hidden');stream.getTracks().forEach(x=>x.stop())};rec.start();status.textContent='Recording…';}catch(e){status.textContent=e.message}};$('#stop').onclick=()=>{if(rec&&rec.state!=='inactive')rec.stop()};$('#view').onclick=previewLast;$('#download').onclick=downloadLast}
